#!/bin/bash
# v5 storyboard keyframes (lyric-driven, full song). CLI nano_banana_flash, ~2cr each.
cd "$(dirname "$0")/.."
ST="Claymation stop-motion film still, Aardman-like plasticine with visible fingerprint texture, miniature handmade clay Korean school-zone neighborhood, red-painted school-zone road surface, soft warm afternoon light, cinematic 16:9. Characters must match the reference images exactly (same face, hair, clothes, colors). Cars have a face only on the windshield. No text, no letters, no words, no logos anywhere; any signboards are blank."
SIG="If a pedestrian signal is visible it is a Korean two-lamp signal: top red-person lamp dark/unlit, bottom green-walking-person lamp lit."
gen(){ id=$1; refs=""; for r in $2; do refs="$refs --image-references $r"; done
  ( url=$(higgsfield generate create nano_banana_flash --prompt "$ST $SIG $3" $refs --aspect_ratio 16:9 --resolution 2k --wait 2>&1 | grep -o 'https://[^ ]*\.png' | tail -1)
    [ -n "$url" ] && curl -s -o "kf3/$id.png" "$url" && echo "$id ok" || echo "$id FAIL" ) & }
B=chars/boy.png; G=chars/grandma.png; T=chars/turtle.png; R=chars/rabbit.png
# verse 1 (boy)
gen V1 "$B $T" "Low camera at a child's eye level on the sidewalk at the edge of a zebra crosswalk: the small boy (reference) stands next to a clay hedge that is as tall as his shoulders, looking up and around, clearly small and easy to miss; further down the road the green turtle-car (reference, turtle shell roof) approaches slowly. Only these two characters."
gen V2 "$B $T" "Medium shot at the edge of a zebra crosswalk: the small boy (reference) raises one hand high above his head so he is easy to see; the green turtle-car (reference, turtle shell roof) has stopped behind the thick white stop line and looks at him with friendly, attentive eyes. Only these two characters."
gen V3 "$B $T" "Over-the-shoulder shot from behind the small boy (reference, red backpack, yellow jacket) standing at the crosswalk edge, checking that the green turtle-car (reference, turtle shell roof) has fully stopped behind the thick white stop line; the turtle-car smiles and nods. Only these two characters."
gen V4s "$B" "Front medium shot: the small boy (reference) stands at the start of a zebra crosswalk with one foot on the curb, turning his head to look to HIS LEFT (screen right) carefully. No other characters, no cars moving."
gen V4e "$B" "Front medium shot, same place and framing: the small boy (reference) has turned his head to look to HIS RIGHT (screen left), and is starting to step forward onto the zebra crosswalk with a confident smile. No other characters."
# verse 2 (grandma)
gen V5 "$G $B" "Low-angle medium shot on a zebra crosswalk: the grandmother (reference) walks slowly and carefully with small steps, gently smiling, holding the boy's (reference) hand; a Korean pedestrian signal behind them with only the bottom green walking-person lamp lit. Only these two characters."
gen V6 "$G $B" "Close-up at hand height: the grandmother's (reference) wrinkled clay hand gently holding the small boy's (reference) hand as they walk side by side across white zebra-crosswalk stripes; her lilac cardigan sleeve and his yellow sleeve visible; warm light. Only their hands, arms and lower bodies."
# chorus 2 / intro / chorus 3
gen N1s "$T $R" "Side-tracking shot on a red school-zone road: the green turtle-car (reference, turtle shell roof) drives slowly and calmly on the right; the red rabbit-car (reference) is just behind it, about to overtake, smug face. Both cars face screen-right and move to screen-right."
gen N1e "$T $R" "Side-tracking shot on the same red school-zone road: the red rabbit-car (reference) has overtaken and is now clearly ahead on the far right, ears flapping, clay dust behind it, smug; the green turtle-car (reference, turtle shell roof) is behind it, calm and smiling. Both cars face screen-right."
gen N2 "$T" "Tracking shot alongside the green turtle-car (reference, turtle shell roof), driving slowly and proudly along a red school-zone road past a clay elementary school fence, its shell gleaming, confident happy face. Only this car, no people on the road."
gen N3 "$T $G $B" "Golden-hour tracking shot: the green turtle-car (reference, turtle shell roof) cruises slowly past the school along the red school-zone road; on the sidewalk the grandmother (reference) and the boy (reference) give it a big thumbs up, smiling. No other characters."
# sign fixes
( url=$(higgsfield generate create nano_banana_flash --prompt "Edit this image. Keep EVERYTHING identical (camera, the young woman with yellow helmet on the electric kick scooter, bicycle lane, cars, houses, cherry tree, lighting, clay style). Only make every shop signboard and banner completely blank (plain colored clay, no letters, no symbols, no logos)." --image-references kf2/A14n.png --aspect_ratio 16:9 --resolution 2k --wait 2>&1 | grep -o 'https://[^ ]*\.png' | tail -1); [ -n "$url" ] && curl -s -o kf3/A14f.png "$url" && echo "A14f ok" || echo "A14f FAIL" ) &
( url=$(higgsfield generate create nano_banana_flash --prompt "Edit this image. Keep EVERYTHING identical (camera, the young woman with yellow helmet on the electric kick scooter, blue bicycle lane, cars, houses, cherry trees, lighting, clay style). Only make every shop signboard completely blank (plain colored clay, no letters, no symbols, no logos)." --image-references keyframes_fix/S09.png --aspect_ratio 9:16 --resolution 2k --wait 2>&1 | grep -o 'https://[^ ]*\.png' | tail -1); [ -n "$url" ] && curl -s -o kf3/S09f.png "$url" && echo "S09f ok" || echo "S09f FAIL" ) &
wait
